-- Tablekeep: every migration in order (11 files).
-- Generated by scripts/combine-migrations.mjs. Don't edit by hand.
-- Paste into Supabase -> SQL Editor -> New query on a NEW project and Run.

-- =====================================================================
-- 0001_health_check.sql
-- =====================================================================

-- 0001: a tiny function the app calls to prove it can reach the database.
-- It reads no tables and returns only the server time.
create or replace function public.health_check()
returns json
language sql
stable
security invoker
set search_path = ''
as $$
  select json_build_object('ok', true, 'time', now());
$$;

revoke all on function public.health_check() from public;
grant execute on function public.health_check() to anon, authenticated;

-- =====================================================================
-- 0002_accounts.sql
-- =====================================================================

-- 0002: accounts. Profiles, the sign-up invite list, and account deletion.
-- Run once in Supabase -> SQL Editor. Safe to re-run.

-- ---------------------------------------------------------------
-- Profiles: one row per user, readable and editable only by them.
-- ---------------------------------------------------------------
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null
    check (char_length(display_name) between 1 and 50),
  created_at timestamptz not null default now()
);

alter table public.profiles enable row level security;

revoke all on public.profiles from anon, authenticated;
grant select on public.profiles to authenticated;
grant update (display_name) on public.profiles to authenticated;

drop policy if exists "Users read their own profile" on public.profiles;
create policy "Users read their own profile"
  on public.profiles for select to authenticated
  using ((select auth.uid()) = id);

drop policy if exists "Users update their own profile" on public.profiles;
create policy "Users update their own profile"
  on public.profiles for update to authenticated
  using ((select auth.uid()) = id)
  with check ((select auth.uid()) = id);
-- No insert or delete policies: rows are created by the trigger below and
-- removed automatically when the user is deleted.

-- Create a profile whenever a user signs up.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name)
  values (
    new.id,
    left(
      coalesce(
        nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''),
        split_part(new.email, '@', 1),
        'Adventurer'
      ),
      50
    )
  );
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------
-- Invite list: only these emails may create an account.
-- Managed by you in Table Editor. Nobody can read it from the app.
-- ---------------------------------------------------------------
create table if not exists public.signup_allowlist (
  email text primary key,
  note text,
  added_at timestamptz not null default now()
);

alter table public.signup_allowlist enable row level security;
revoke all on public.signup_allowlist from anon, authenticated;

-- Called by Supabase Auth before creating any user
-- (enable it under Authentication -> Hooks -> Before User Created).
create or replace function public.hook_before_user_created(event jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  new_email text := lower(trim(event -> 'user' ->> 'email'));
begin
  if new_email is not null and exists (
    select 1 from public.signup_allowlist a
    where lower(trim(a.email)) = new_email
  ) then
    return '{}'::jsonb;
  end if;

  return jsonb_build_object(
    'error', jsonb_build_object(
      'http_code', 403,
      'message', 'This email is not on the invite list.'
    )
  );
end;
$$;

grant usage on schema public to supabase_auth_admin;
grant execute on function public.hook_before_user_created(jsonb)
  to supabase_auth_admin;
revoke execute on function public.hook_before_user_created(jsonb)
  from public, anon, authenticated;

-- ---------------------------------------------------------------
-- Account deletion: a signed-in user can delete only themselves.
-- Their profile is removed by the cascade on profiles.id.
-- ---------------------------------------------------------------
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  delete from auth.users where id = auth.uid();
end;
$$;

revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- =====================================================================
-- 0003_campaigns.sql
-- =====================================================================

-- 0003: campaigns, memberships and invite links.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

create extension if not exists pgcrypto with schema extensions;

do $$ begin
  create type public.campaign_role as enum ('owner', 'co_dm', 'player');
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------
create table if not exists public.campaigns (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 80),
  game_system text not null default '' check (char_length(game_system) <= 60),
  description text not null default '' check (char_length(description) <= 2000),
  status text not null default 'active' check (status in ('active', 'archived')),
  created_at timestamptz not null default now()
);

create table if not exists public.campaign_members (
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  role public.campaign_role not null default 'player',
  joined_at timestamptz not null default now(),
  primary key (campaign_id, user_id)
);
create unique index if not exists campaign_members_one_owner
  on public.campaign_members (campaign_id) where role = 'owner';
create index if not exists campaign_members_user_idx
  on public.campaign_members (user_id);

create table if not exists public.campaign_invites (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  token_hash text not null unique,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  max_uses integer not null check (max_uses between 1 and 100),
  uses integer not null default 0,
  revoked_at timestamptz
);
create index if not exists campaign_invites_campaign_idx
  on public.campaign_invites (campaign_id);

alter table public.campaigns enable row level security;
alter table public.campaign_members enable row level security;
alter table public.campaign_invites enable row level security;

revoke all on public.campaigns from anon, authenticated;
revoke all on public.campaign_members from anon, authenticated;
revoke all on public.campaign_invites from anon, authenticated;

-- ---------------------------------------------------------------
-- Helper checks used by the security rules
-- ---------------------------------------------------------------
create or replace function public.my_campaign_role(p_campaign uuid)
returns public.campaign_role
language sql stable security definer set search_path = ''
as $$
  select m.role from public.campaign_members m
  where m.campaign_id = p_campaign and m.user_id = auth.uid();
$$;

create or replace function public.is_campaign_member(p_campaign uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select public.my_campaign_role(p_campaign) is not null;
$$;

create or replace function public.is_campaign_manager(p_campaign uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce(public.my_campaign_role(p_campaign) in ('owner', 'co_dm'), false);
$$;

create or replace function public.shares_campaign_with(p_user uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.campaign_members me
    join public.campaign_members them on them.campaign_id = me.campaign_id
    where me.user_id = auth.uid() and them.user_id = p_user
  );
$$;

revoke execute on function public.my_campaign_role(uuid) from public, anon;
revoke execute on function public.is_campaign_member(uuid) from public, anon;
revoke execute on function public.is_campaign_manager(uuid) from public, anon;
revoke execute on function public.shares_campaign_with(uuid) from public, anon;
grant execute on function public.my_campaign_role(uuid) to authenticated;
grant execute on function public.is_campaign_member(uuid) to authenticated;
grant execute on function public.is_campaign_manager(uuid) to authenticated;
grant execute on function public.shares_campaign_with(uuid) to authenticated;

-- ---------------------------------------------------------------
-- Security rules (Row Level Security)
-- ---------------------------------------------------------------
grant select on public.campaigns to authenticated;
grant update (name, game_system, description, status) on public.campaigns to authenticated;

drop policy if exists "Members see their campaigns" on public.campaigns;
create policy "Members see their campaigns"
  on public.campaigns for select to authenticated
  using (public.is_campaign_member(id));

drop policy if exists "Managers edit their campaigns" on public.campaigns;
create policy "Managers edit their campaigns"
  on public.campaigns for update to authenticated
  using (public.is_campaign_manager(id))
  with check (public.is_campaign_manager(id));

grant select on public.campaign_members to authenticated;

drop policy if exists "Members see fellow members" on public.campaign_members;
create policy "Members see fellow members"
  on public.campaign_members for select to authenticated
  using (public.is_campaign_member(campaign_id));

-- The token hash is deliberately not readable by anyone.
grant select (id, campaign_id, created_by, created_at, expires_at, max_uses, uses, revoked_at)
  on public.campaign_invites to authenticated;

drop policy if exists "Managers see invite links" on public.campaign_invites;
create policy "Managers see invite links"
  on public.campaign_invites for select to authenticated
  using (public.is_campaign_manager(campaign_id));

drop policy if exists "Members read fellow members' profiles" on public.profiles;
create policy "Members read fellow members' profiles"
  on public.profiles for select to authenticated
  using (public.shares_campaign_with(id));

-- ---------------------------------------------------------------
-- Actions. All membership changes go through these functions, which
-- check permissions first. Errors are short codes the app translates.
-- ---------------------------------------------------------------
create or replace function public.create_campaign(
  p_name text, p_game_system text default '', p_description text default ''
)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'not_signed_in'; end if;
  insert into public.campaigns (name, game_system, description)
  values (trim(p_name), trim(coalesce(p_game_system, '')), trim(coalesce(p_description, '')))
  returning id into v_id;
  insert into public.campaign_members (campaign_id, user_id, role)
  values (v_id, v_uid, 'owner');
  return v_id;
end;
$$;

create or replace function public.delete_campaign(p_campaign uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if public.my_campaign_role(p_campaign) is distinct from 'owner' then
    raise exception 'not_allowed';
  end if;
  delete from public.campaigns where id = p_campaign;
end;
$$;

create or replace function public.create_invite(
  p_campaign uuid, p_days integer default 7, p_max_uses integer default 10
)
returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_token text;
begin
  if not public.is_campaign_manager(p_campaign) then
    raise exception 'not_allowed';
  end if;
  if p_days is null or p_days not between 1 and 30
     or p_max_uses is null or p_max_uses not between 1 and 100 then
    raise exception 'invalid_input';
  end if;
  if exists (select 1 from public.campaigns
             where id = p_campaign and status = 'archived') then
    raise exception 'campaign_archived';
  end if;

  v_token := encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.campaign_invites
    (campaign_id, token_hash, created_by, expires_at, max_uses)
  values (
    p_campaign,
    encode(extensions.digest(v_token, 'sha256'), 'hex'),
    auth.uid(),
    now() + make_interval(days => p_days),
    p_max_uses
  );
  return v_token;
end;
$$;

create or replace function public.revoke_invite(p_invite uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_campaign uuid;
begin
  select campaign_id into v_campaign
  from public.campaign_invites where id = p_invite;
  if v_campaign is null or not public.is_campaign_manager(v_campaign) then
    raise exception 'not_allowed';
  end if;
  update public.campaign_invites
  set revoked_at = now()
  where id = p_invite and revoked_at is null;
end;
$$;

create or replace function public.preview_invite(p_token text)
returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  v public.campaign_invites;
  v_campaign public.campaigns;
  v_dm text;
  v_state text;
begin
  select * into v from public.campaign_invites
  where token_hash = encode(extensions.digest(coalesce(p_token, ''), 'sha256'), 'hex');
  if not found then
    return jsonb_build_object('state', 'invalid');
  end if;

  select * into v_campaign from public.campaigns where id = v.campaign_id;
  select p.display_name into v_dm
  from public.campaign_members m
  join public.profiles p on p.id = m.user_id
  where m.campaign_id = v.campaign_id and m.role = 'owner';

  v_state := case
    when auth.uid() is not null and exists (
      select 1 from public.campaign_members
      where campaign_id = v.campaign_id and user_id = auth.uid()
    ) then 'already_member'
    when v.revoked_at is not null then 'revoked'
    when v.expires_at <= now() then 'expired'
    when v.uses >= v.max_uses then 'used_up'
    when v_campaign.status = 'archived' then 'archived'
    else 'ok'
  end;

  return jsonb_build_object(
    'state', v_state,
    'campaign_id', case when v_state = 'already_member' then v.campaign_id end,
    'campaign_name', v_campaign.name,
    'game_system', v_campaign.game_system,
    'dm_name', v_dm
  );
end;
$$;

create or replace function public.join_campaign(p_token text)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v public.campaign_invites;
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_signed_in'; end if;

  select * into v from public.campaign_invites
  where token_hash = encode(extensions.digest(coalesce(p_token, ''), 'sha256'), 'hex')
  for update;
  if not found then raise exception 'invite_invalid'; end if;

  if exists (select 1 from public.campaign_members
             where campaign_id = v.campaign_id and user_id = v_uid) then
    return v.campaign_id;
  end if;
  if v.revoked_at is not null then raise exception 'invite_revoked'; end if;
  if v.expires_at <= now() then raise exception 'invite_expired'; end if;
  if v.uses >= v.max_uses then raise exception 'invite_used_up'; end if;
  if exists (select 1 from public.campaigns
             where id = v.campaign_id and status = 'archived') then
    raise exception 'campaign_archived';
  end if;

  insert into public.campaign_members (campaign_id, user_id, role)
  values (v.campaign_id, v_uid, 'player');
  update public.campaign_invites set uses = uses + 1 where id = v.id;
  return v.campaign_id;
end;
$$;

create or replace function public.set_member_role(
  p_campaign uuid, p_user uuid, p_role public.campaign_role
)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_target public.campaign_role;
begin
  if public.my_campaign_role(p_campaign) is distinct from 'owner' then
    raise exception 'not_allowed';
  end if;
  if p_role = 'owner' then raise exception 'invalid_input'; end if;
  select role into v_target from public.campaign_members
  where campaign_id = p_campaign and user_id = p_user;
  if v_target is null then raise exception 'not_a_member'; end if;
  if v_target = 'owner' then raise exception 'not_allowed'; end if;
  update public.campaign_members set role = p_role
  where campaign_id = p_campaign and user_id = p_user;
end;
$$;

create or replace function public.remove_member(p_campaign uuid, p_user uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_me public.campaign_role := public.my_campaign_role(p_campaign);
  v_target public.campaign_role;
begin
  if p_user = auth.uid() then raise exception 'use_leave'; end if;
  select role into v_target from public.campaign_members
  where campaign_id = p_campaign and user_id = p_user;
  if v_target is null then raise exception 'not_a_member'; end if;
  if not (v_me = 'owner' or (v_me = 'co_dm' and v_target = 'player')) then
    raise exception 'not_allowed';
  end if;
  delete from public.campaign_members
  where campaign_id = p_campaign and user_id = p_user;
end;
$$;

create or replace function public.leave_campaign(p_campaign uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_me public.campaign_role := public.my_campaign_role(p_campaign);
begin
  if v_me is null then raise exception 'not_a_member'; end if;
  if v_me = 'owner' then raise exception 'owner_cannot_leave'; end if;
  delete from public.campaign_members
  where campaign_id = p_campaign and user_id = auth.uid();
end;
$$;

create or replace function public.transfer_ownership(p_campaign uuid, p_new_owner uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if public.my_campaign_role(p_campaign) is distinct from 'owner' then
    raise exception 'not_allowed';
  end if;
  if p_new_owner = auth.uid() or not exists (
    select 1 from public.campaign_members
    where campaign_id = p_campaign and user_id = p_new_owner
  ) then
    raise exception 'not_a_member';
  end if;
  -- Step down first: a campaign can only ever have one owner.
  update public.campaign_members set role = 'co_dm'
  where campaign_id = p_campaign and user_id = auth.uid();
  update public.campaign_members set role = 'owner'
  where campaign_id = p_campaign and user_id = p_new_owner;
end;
$$;

-- Owners must hand over or delete their campaigns before deleting
-- their account, so no campaign is ever left without an owner.
create or replace function public.delete_my_account()
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  if exists (select 1 from public.campaign_members
             where user_id = auth.uid() and role = 'owner') then
    raise exception 'owns_campaigns';
  end if;
  delete from auth.users where id = auth.uid();
end;
$$;

revoke execute on function public.create_campaign(text, text, text) from public, anon;
revoke execute on function public.delete_campaign(uuid) from public, anon;
revoke execute on function public.create_invite(uuid, integer, integer) from public, anon;
revoke execute on function public.revoke_invite(uuid) from public, anon;
revoke execute on function public.preview_invite(text) from public;
revoke execute on function public.join_campaign(text) from public, anon;
revoke execute on function public.set_member_role(uuid, uuid, public.campaign_role) from public, anon;
revoke execute on function public.remove_member(uuid, uuid) from public, anon;
revoke execute on function public.leave_campaign(uuid) from public, anon;
revoke execute on function public.transfer_ownership(uuid, uuid) from public, anon;
revoke execute on function public.delete_my_account() from public, anon;

grant execute on function public.create_campaign(text, text, text) to authenticated;
grant execute on function public.delete_campaign(uuid) to authenticated;
grant execute on function public.create_invite(uuid, integer, integer) to authenticated;
grant execute on function public.revoke_invite(uuid) to authenticated;
grant execute on function public.preview_invite(text) to anon, authenticated;
grant execute on function public.join_campaign(text) to authenticated;
grant execute on function public.set_member_role(uuid, uuid, public.campaign_role) to authenticated;
grant execute on function public.remove_member(uuid, uuid) to authenticated;
grant execute on function public.leave_campaign(uuid) to authenticated;
grant execute on function public.transfer_ownership(uuid, uuid) to authenticated;
grant execute on function public.delete_my_account() to authenticated;

-- =====================================================================
-- 0004_templates.sql
-- =====================================================================

-- 0004: character sheet templates with drafts and frozen published versions.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

create table if not exists public.sheet_templates (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  game_system text not null default '' check (char_length(game_system) <= 60),
  description text not null default '' check (char_length(description) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists sheet_templates_owner_idx on public.sheet_templates (owner_id);

create table if not exists public.sheet_template_versions (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null references public.sheet_templates (id) on delete cascade,
  status text not null check (status in ('draft', 'published')),
  version_number integer,
  definition jsonb not null
    check (jsonb_typeof(definition) = 'object' and octet_length(definition::text) < 262144),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz,
  check (
    (status = 'draft' and version_number is null and published_at is null)
    or (status = 'published' and version_number >= 1 and published_at is not null)
  ),
  unique (template_id, version_number)
);
create unique index if not exists sheet_template_versions_one_draft
  on public.sheet_template_versions (template_id) where status = 'draft';

alter table public.sheet_templates enable row level security;
alter table public.sheet_template_versions enable row level security;
revoke all on public.sheet_templates from anon, authenticated;
revoke all on public.sheet_template_versions from anon, authenticated;

-- Published versions are frozen forever; drafts get a fresh "updated" time.
create or replace function public.sheet_template_versions_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.status = 'published' then
    raise exception 'version_published';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists sheet_template_versions_guard on public.sheet_template_versions;
create trigger sheet_template_versions_guard
  before update on public.sheet_template_versions
  for each row execute function public.sheet_template_versions_guard();

create or replace function public.owns_template(p_template uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.sheet_templates
    where id = p_template and owner_id = auth.uid()
  );
$$;
revoke execute on function public.owns_template(uuid) from public, anon;
grant execute on function public.owns_template(uuid) to authenticated;

-- Owners read and rename their own templates.
grant select on public.sheet_templates to authenticated;
grant update (name, game_system, description) on public.sheet_templates to authenticated;

drop policy if exists "Owners see their templates" on public.sheet_templates;
create policy "Owners see their templates"
  on public.sheet_templates for select to authenticated
  using (owner_id = (select auth.uid()));

drop policy if exists "Owners edit their templates" on public.sheet_templates;
create policy "Owners edit their templates"
  on public.sheet_templates for update to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

-- Owners read every version, but can only edit the draft's definition.
grant select on public.sheet_template_versions to authenticated;
grant update (definition) on public.sheet_template_versions to authenticated;

drop policy if exists "Owners see their template versions" on public.sheet_template_versions;
create policy "Owners see their template versions"
  on public.sheet_template_versions for select to authenticated
  using (public.owns_template(template_id));

drop policy if exists "Owners edit their drafts" on public.sheet_template_versions;
create policy "Owners edit their drafts"
  on public.sheet_template_versions for update to authenticated
  using (status = 'draft' and public.owns_template(template_id))
  with check (status = 'draft' and public.owns_template(template_id));

-- ---------------------------------------------------------------
-- Actions
-- ---------------------------------------------------------------
create or replace function public.create_template(
  p_name text, p_game_system text, p_description text, p_definition jsonb
)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_signed_in'; end if;
  insert into public.sheet_templates (owner_id, name, game_system, description)
  values (auth.uid(), trim(p_name), trim(coalesce(p_game_system, '')), trim(coalesce(p_description, '')))
  returning id into v_id;
  insert into public.sheet_template_versions (template_id, status, definition)
  values (v_id, 'draft', p_definition);
  return v_id;
end;
$$;

create or replace function public.publish_template(p_template uuid)
returns integer
language plpgsql security definer set search_path = ''
as $$
declare
  v_draft uuid;
  v_next integer;
begin
  if not public.owns_template(p_template) then raise exception 'not_allowed'; end if;
  select id into v_draft from public.sheet_template_versions
  where template_id = p_template and status = 'draft'
  for update;
  if v_draft is null then raise exception 'no_draft'; end if;

  select coalesce(max(version_number), 0) + 1 into v_next
  from public.sheet_template_versions
  where template_id = p_template and status = 'published';

  update public.sheet_template_versions
  set status = 'published', version_number = v_next, published_at = now()
  where id = v_draft;
  update public.sheet_templates set updated_at = now() where id = p_template;
  return v_next;
end;
$$;

-- Returns the draft, creating one from the latest published version if needed.
create or replace function public.start_template_draft(p_template uuid)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_draft uuid;
  v_definition jsonb;
begin
  if not public.owns_template(p_template) then raise exception 'not_allowed'; end if;
  select id into v_draft from public.sheet_template_versions
  where template_id = p_template and status = 'draft';
  if v_draft is not null then return v_draft; end if;

  select definition into v_definition from public.sheet_template_versions
  where template_id = p_template and status = 'published'
  order by version_number desc limit 1;
  if v_definition is null then raise exception 'no_versions'; end if;

  insert into public.sheet_template_versions (template_id, status, definition)
  values (p_template, 'draft', v_definition)
  returning id into v_draft;
  return v_draft;
end;
$$;

create or replace function public.discard_template_draft(p_template uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.owns_template(p_template) then raise exception 'not_allowed'; end if;
  if not exists (select 1 from public.sheet_template_versions
                 where template_id = p_template and status = 'published') then
    raise exception 'only_draft';
  end if;
  delete from public.sheet_template_versions
  where template_id = p_template and status = 'draft';
end;
$$;

create or replace function public.duplicate_template(p_template uuid)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_source public.sheet_templates;
  v_definition jsonb;
  v_id uuid;
begin
  if not public.owns_template(p_template) then raise exception 'not_allowed'; end if;
  select * into v_source from public.sheet_templates where id = p_template;
  select definition into v_definition from public.sheet_template_versions
  where template_id = p_template
  order by (status = 'draft') desc, version_number desc nulls last
  limit 1;

  insert into public.sheet_templates (owner_id, name, game_system, description)
  values (auth.uid(), left('Copy of ' || v_source.name, 80), v_source.game_system, v_source.description)
  returning id into v_id;
  insert into public.sheet_template_versions (template_id, status, definition)
  values (v_id, 'draft', v_definition);
  return v_id;
end;
$$;

create or replace function public.delete_template(p_template uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.owns_template(p_template) then raise exception 'not_allowed'; end if;
  delete from public.sheet_templates where id = p_template;
end;
$$;

revoke execute on function public.create_template(text, text, text, jsonb) from public, anon;
revoke execute on function public.publish_template(uuid) from public, anon;
revoke execute on function public.start_template_draft(uuid) from public, anon;
revoke execute on function public.discard_template_draft(uuid) from public, anon;
revoke execute on function public.duplicate_template(uuid) from public, anon;
revoke execute on function public.delete_template(uuid) from public, anon;
grant execute on function public.create_template(text, text, text, jsonb) to authenticated;
grant execute on function public.publish_template(uuid) to authenticated;
grant execute on function public.start_template_draft(uuid) to authenticated;
grant execute on function public.discard_template_draft(uuid) to authenticated;
grant execute on function public.duplicate_template(uuid) to authenticated;
grant execute on function public.delete_template(uuid) to authenticated;

-- =====================================================================
-- 0005_characters.sql
-- =====================================================================

-- 0005: characters (pinned to a published template version) and restore points.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

create table if not exists public.characters (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  -- No "on delete" rule: a template version in use can't be deleted.
  template_version_id uuid not null references public.sheet_template_versions (id),
  data jsonb not null default '{}'::jsonb
    check (jsonb_typeof(data) = 'object' and octet_length(data::text) < 262144),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists characters_owner_idx on public.characters (owner_id);
create index if not exists characters_version_idx on public.characters (template_version_id);

create table if not exists public.character_snapshots (
  id uuid primary key default gen_random_uuid(),
  character_id uuid not null references public.characters (id) on delete cascade,
  label text not null default '' check (char_length(label) <= 80),
  reason text not null check (reason in ('manual', 'before_restore')),
  data jsonb not null,
  created_at timestamptz not null default now()
);
create index if not exists character_snapshots_character_idx
  on public.character_snapshots (character_id, created_at desc);

alter table public.characters enable row level security;
alter table public.character_snapshots enable row level security;
revoke all on public.characters from anon, authenticated;
revoke all on public.character_snapshots from anon, authenticated;

-- Every change gets a fresh timestamp, which autosave uses to spot
-- edits made on another device in the meantime.
create or replace function public.characters_touch()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end;
$$;

drop trigger if exists characters_touch on public.characters;
create trigger characters_touch
  before update on public.characters
  for each row execute function public.characters_touch();

create or replace function public.owns_character(p_character uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.characters
    where id = p_character and owner_id = auth.uid()
  );
$$;
revoke execute on function public.owns_character(uuid) from public, anon;
grant execute on function public.owns_character(uuid) to authenticated;

grant select on public.characters to authenticated;
grant update (name, data) on public.characters to authenticated;

drop policy if exists "Owners see their characters" on public.characters;
create policy "Owners see their characters"
  on public.characters for select to authenticated
  using (owner_id = (select auth.uid()));

drop policy if exists "Owners edit their characters" on public.characters;
create policy "Owners edit their characters"
  on public.characters for update to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

grant select on public.character_snapshots to authenticated;

drop policy if exists "Owners see their restore points" on public.character_snapshots;
create policy "Owners see their restore points"
  on public.character_snapshots for select to authenticated
  using (public.owns_character(character_id));

-- ---------------------------------------------------------------
-- Actions
-- ---------------------------------------------------------------

-- Who may build a character from this version? For now: the template owner.
-- (Phase 4b adds templates a campaign offers to its members.)
create or replace function public.can_use_template_version(p_version uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.sheet_template_versions v
    join public.sheet_templates t on t.id = v.template_id
    where v.id = p_version and v.status = 'published' and t.owner_id = auth.uid()
  );
$$;
revoke execute on function public.can_use_template_version(uuid) from public, anon;
grant execute on function public.can_use_template_version(uuid) to authenticated;

create or replace function public.create_character(p_name text, p_template_version uuid)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_signed_in'; end if;
  if exists (select 1 from public.sheet_template_versions
             where id = p_template_version and status = 'draft') then
    raise exception 'not_published';
  end if;
  if not public.can_use_template_version(p_template_version) then
    raise exception 'not_allowed';
  end if;
  insert into public.characters (owner_id, name, template_version_id)
  values (auth.uid(), trim(p_name), p_template_version)
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.duplicate_character(p_character uuid)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_source public.characters;
  v_id uuid;
begin
  if not public.owns_character(p_character) then raise exception 'not_allowed'; end if;
  select * into v_source from public.characters where id = p_character;
  insert into public.characters (owner_id, name, template_version_id, data)
  values (auth.uid(), left('Copy of ' || v_source.name, 80), v_source.template_version_id, v_source.data)
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.delete_character(p_character uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.owns_character(p_character) then raise exception 'not_allowed'; end if;
  delete from public.characters where id = p_character;
end;
$$;

-- Saves the character as it is now. Keeps the newest 50 restore points.
create or replace function public.create_character_snapshot(p_character uuid, p_label text default '')
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.owns_character(p_character) then raise exception 'not_allowed'; end if;
  insert into public.character_snapshots (character_id, label, reason, data)
  select id, left(trim(coalesce(p_label, '')), 80), 'manual', data
  from public.characters where id = p_character
  returning id into v_id;

  delete from public.character_snapshots
  where character_id = p_character and id in (
    select id from public.character_snapshots
    where character_id = p_character
    order by created_at desc
    offset 50
  );
  return v_id;
end;
$$;

-- Puts a restore point back, saving the current state first so it can be undone.
create or replace function public.restore_character_snapshot(p_snapshot uuid)
returns timestamptz
language plpgsql security definer set search_path = ''
as $$
declare
  v_snapshot public.character_snapshots;
  v_updated timestamptz;
begin
  select * into v_snapshot from public.character_snapshots where id = p_snapshot;
  if v_snapshot.id is null or not public.owns_character(v_snapshot.character_id) then
    raise exception 'not_allowed';
  end if;

  insert into public.character_snapshots (character_id, label, reason, data)
  select id, 'Before restoring', 'before_restore', data
  from public.characters where id = v_snapshot.character_id;

  update public.characters set data = v_snapshot.data
  where id = v_snapshot.character_id
  returning updated_at into v_updated;
  return v_updated;
end;
$$;

create or replace function public.delete_character_snapshot(p_snapshot uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_character uuid;
begin
  select character_id into v_character from public.character_snapshots where id = p_snapshot;
  if v_character is null or not public.owns_character(v_character) then
    raise exception 'not_allowed';
  end if;
  delete from public.character_snapshots where id = p_snapshot;
end;
$$;

-- Templates can't be deleted while a character still uses one of their versions.
create or replace function public.delete_template(p_template uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.owns_template(p_template) then raise exception 'not_allowed'; end if;
  if exists (
    select 1 from public.characters c
    join public.sheet_template_versions v on v.id = c.template_version_id
    where v.template_id = p_template
  ) then
    raise exception 'template_in_use';
  end if;
  delete from public.sheet_templates where id = p_template;
end;
$$;

revoke execute on function public.create_character(text, uuid) from public, anon;
revoke execute on function public.duplicate_character(uuid) from public, anon;
revoke execute on function public.delete_character(uuid) from public, anon;
revoke execute on function public.create_character_snapshot(uuid, text) from public, anon;
revoke execute on function public.restore_character_snapshot(uuid) from public, anon;
revoke execute on function public.delete_character_snapshot(uuid) from public, anon;
revoke execute on function public.delete_template(uuid) from public, anon;
grant execute on function public.create_character(text, uuid) to authenticated;
grant execute on function public.duplicate_character(uuid) to authenticated;
grant execute on function public.delete_character(uuid) to authenticated;
grant execute on function public.create_character_snapshot(uuid, text) to authenticated;
grant execute on function public.restore_character_snapshot(uuid) to authenticated;
grant execute on function public.delete_character_snapshot(uuid) to authenticated;
grant execute on function public.delete_template(uuid) to authenticated;

-- =====================================================================
-- 0006_party.sql
-- =====================================================================

-- 0006: inventory, templates offered by campaigns, characters in campaigns,
-- and who can see which character sheets.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

-- ---------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------
alter table public.campaigns
  add column if not exists players_see_full_sheets boolean not null default false;
grant update (players_see_full_sheets) on public.campaigns to authenticated;

create table if not exists public.inventory_items (
  id uuid primary key default gen_random_uuid(),
  character_id uuid not null references public.characters (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  quantity integer not null default 1 check (quantity between 0 and 1000000),
  weight numeric(10, 2) check (weight is null or (weight >= 0 and weight <= 100000)),
  notes text not null default '' check (char_length(notes) <= 500),
  created_at timestamptz not null default now()
);
create index if not exists inventory_items_character_idx
  on public.inventory_items (character_id, created_at);

create table if not exists public.campaign_templates (
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  template_version_id uuid not null references public.sheet_template_versions (id) on delete cascade,
  added_by uuid references auth.users (id) on delete set null,
  added_at timestamptz not null default now(),
  primary key (campaign_id, template_version_id)
);

create table if not exists public.campaign_characters (
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  -- unique: a character is in at most one campaign at a time
  character_id uuid not null unique references public.characters (id) on delete cascade,
  added_at timestamptz not null default now(),
  primary key (campaign_id, character_id)
);

alter table public.inventory_items enable row level security;
alter table public.campaign_templates enable row level security;
alter table public.campaign_characters enable row level security;
revoke all on public.inventory_items from anon, authenticated;
revoke all on public.campaign_templates from anon, authenticated;
revoke all on public.campaign_characters from anon, authenticated;

-- ---------------------------------------------------------------
-- Who can see what
-- ---------------------------------------------------------------

-- Owner always; the campaign's DM and Co-DMs; other players only when the
-- campaign allows full sheets.
create or replace function public.can_view_character(p_character uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.characters ch
    where ch.id = p_character and ch.owner_id = auth.uid()
  ) or exists (
    select 1
    from public.campaign_characters cc
    join public.campaigns c on c.id = cc.campaign_id
    where cc.character_id = p_character
      and (
        public.is_campaign_manager(cc.campaign_id)
        or (c.players_see_full_sheets and public.is_campaign_member(cc.campaign_id))
      )
  );
$$;

-- A template version is readable by its owner, by members of a campaign
-- that offers it, and by anyone who can see a character built from it.
create or replace function public.can_read_template_version(p_version uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.sheet_template_versions v
    join public.sheet_templates t on t.id = v.template_id
    where v.id = p_version and t.owner_id = auth.uid()
  ) or exists (
    select 1 from public.campaign_templates ct
    where ct.template_version_id = p_version and public.is_campaign_member(ct.campaign_id)
  ) or exists (
    select 1 from public.characters ch
    where ch.template_version_id = p_version and public.can_view_character(ch.id)
  );
$$;

create or replace function public.can_read_template(p_template uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.sheet_template_versions v
    where v.template_id = p_template
      and v.status = 'published'
      and public.can_read_template_version(v.id)
  );
$$;

-- Building characters: from your own published versions, or from versions
-- a campaign you belong to offers.
create or replace function public.can_use_template_version(p_version uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.sheet_template_versions v
    join public.sheet_templates t on t.id = v.template_id
    where v.id = p_version and v.status = 'published' and t.owner_id = auth.uid()
  ) or exists (
    select 1
    from public.campaign_templates ct
    join public.sheet_template_versions v on v.id = ct.template_version_id
    where ct.template_version_id = p_version
      and v.status = 'published'
      and public.is_campaign_member(ct.campaign_id)
  );
$$;

revoke execute on function public.can_view_character(uuid) from public, anon;
revoke execute on function public.can_read_template_version(uuid) from public, anon;
revoke execute on function public.can_read_template(uuid) from public, anon;
grant execute on function public.can_view_character(uuid) to authenticated;
grant execute on function public.can_read_template_version(uuid) to authenticated;
grant execute on function public.can_read_template(uuid) to authenticated;

drop policy if exists "Campaign viewers see party characters" on public.characters;
create policy "Campaign viewers see party characters"
  on public.characters for select to authenticated
  using (public.can_view_character(id));

drop policy if exists "Shared template versions are readable" on public.sheet_template_versions;
create policy "Shared template versions are readable"
  on public.sheet_template_versions for select to authenticated
  using (status = 'published' and public.can_read_template_version(id));

drop policy if exists "Shared templates are readable" on public.sheet_templates;
create policy "Shared templates are readable"
  on public.sheet_templates for select to authenticated
  using (public.can_read_template(id));

-- Inventory: visible like the character, editable only by its owner.
grant select on public.inventory_items to authenticated;
grant insert (character_id, name, quantity, weight, notes) on public.inventory_items to authenticated;
grant update (name, quantity, weight, notes) on public.inventory_items to authenticated;
grant delete on public.inventory_items to authenticated;

drop policy if exists "Inventory visible with the character" on public.inventory_items;
create policy "Inventory visible with the character"
  on public.inventory_items for select to authenticated
  using (public.can_view_character(character_id));

drop policy if exists "Owners add inventory" on public.inventory_items;
create policy "Owners add inventory"
  on public.inventory_items for insert to authenticated
  with check (public.owns_character(character_id));

drop policy if exists "Owners edit inventory" on public.inventory_items;
create policy "Owners edit inventory"
  on public.inventory_items for update to authenticated
  using (public.owns_character(character_id))
  with check (public.owns_character(character_id));

drop policy if exists "Owners remove inventory" on public.inventory_items;
create policy "Owners remove inventory"
  on public.inventory_items for delete to authenticated
  using (public.owns_character(character_id));

grant select on public.campaign_templates to authenticated;
drop policy if exists "Members see offered templates" on public.campaign_templates;
create policy "Members see offered templates"
  on public.campaign_templates for select to authenticated
  using (public.is_campaign_member(campaign_id));

grant select on public.campaign_characters to authenticated;
drop policy if exists "Members see the party" on public.campaign_characters;
create policy "Members see the party"
  on public.campaign_characters for select to authenticated
  using (public.is_campaign_member(campaign_id) or public.owns_character(character_id));

-- ---------------------------------------------------------------
-- Actions
-- ---------------------------------------------------------------
create or replace function public.offer_template_in_campaign(p_campaign uuid, p_version uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.is_campaign_manager(p_campaign) then raise exception 'not_allowed'; end if;
  if not exists (
    select 1 from public.sheet_template_versions v
    join public.sheet_templates t on t.id = v.template_id
    where v.id = p_version and v.status = 'published' and t.owner_id = auth.uid()
  ) then
    raise exception 'not_your_template';
  end if;
  insert into public.campaign_templates (campaign_id, template_version_id, added_by)
  values (p_campaign, p_version, auth.uid())
  on conflict do nothing;
end;
$$;

create or replace function public.withdraw_template_from_campaign(p_campaign uuid, p_version uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.is_campaign_manager(p_campaign) then raise exception 'not_allowed'; end if;
  delete from public.campaign_templates
  where campaign_id = p_campaign and template_version_id = p_version;
end;
$$;

create or replace function public.add_character_to_campaign(p_campaign uuid, p_character uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.owns_character(p_character) then raise exception 'not_allowed'; end if;
  if not public.is_campaign_member(p_campaign) then raise exception 'not_allowed'; end if;
  if exists (select 1 from public.campaigns where id = p_campaign and status = 'archived') then
    raise exception 'campaign_archived';
  end if;
  if exists (select 1 from public.campaign_characters where character_id = p_character) then
    raise exception 'character_in_campaign';
  end if;
  insert into public.campaign_characters (campaign_id, character_id)
  values (p_campaign, p_character);
end;
$$;

create or replace function public.remove_character_from_campaign(p_campaign uuid, p_character uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not (public.owns_character(p_character) or public.is_campaign_manager(p_campaign)) then
    raise exception 'not_allowed';
  end if;
  delete from public.campaign_characters
  where campaign_id = p_campaign and character_id = p_character;
end;
$$;

-- The party list every member may see: names only, plus whether you may
-- open each sheet.
create or replace function public.campaign_party(p_campaign uuid)
returns table (
  character_id uuid,
  character_name text,
  owner_id uuid,
  owner_name text,
  template_name text,
  version_number integer,
  can_view boolean
)
language plpgsql stable security definer set search_path = ''
as $$
begin
  if not public.is_campaign_member(p_campaign) then raise exception 'not_allowed'; end if;
  return query
    select ch.id, ch.name, ch.owner_id, coalesce(p.display_name, 'Unknown player'),
           t.name, v.version_number, public.can_view_character(ch.id)
    from public.campaign_characters cc
    join public.characters ch on ch.id = cc.character_id
    join public.sheet_template_versions v on v.id = ch.template_version_id
    join public.sheet_templates t on t.id = v.template_id
    left join public.profiles p on p.id = ch.owner_id
    where cc.campaign_id = p_campaign
    order by ch.name;
end;
$$;

-- When someone leaves or is removed, their characters leave the party too.
create or replace function public.campaign_members_after_delete()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  delete from public.campaign_characters cc
  using public.characters ch
  where cc.character_id = ch.id
    and cc.campaign_id = old.campaign_id
    and ch.owner_id = old.user_id;
  return old;
end;
$$;

drop trigger if exists campaign_members_after_delete on public.campaign_members;
create trigger campaign_members_after_delete
  after delete on public.campaign_members
  for each row execute function public.campaign_members_after_delete();

-- Accounts can't be deleted while other players' characters use their templates.
create or replace function public.delete_my_account()
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  if exists (select 1 from public.campaign_members
             where user_id = auth.uid() and role = 'owner') then
    raise exception 'owns_campaigns';
  end if;
  if exists (
    select 1 from public.characters ch
    join public.sheet_template_versions v on v.id = ch.template_version_id
    join public.sheet_templates t on t.id = v.template_id
    where t.owner_id = auth.uid() and ch.owner_id <> auth.uid()
  ) then
    raise exception 'templates_in_use';
  end if;
  delete from auth.users where id = auth.uid();
end;
$$;

revoke execute on function public.offer_template_in_campaign(uuid, uuid) from public, anon;
revoke execute on function public.withdraw_template_from_campaign(uuid, uuid) from public, anon;
revoke execute on function public.add_character_to_campaign(uuid, uuid) from public, anon;
revoke execute on function public.remove_character_from_campaign(uuid, uuid) from public, anon;
revoke execute on function public.campaign_party(uuid) from public, anon;
revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.offer_template_in_campaign(uuid, uuid) to authenticated;
grant execute on function public.withdraw_template_from_campaign(uuid, uuid) to authenticated;
grant execute on function public.add_character_to_campaign(uuid, uuid) to authenticated;
grant execute on function public.remove_character_from_campaign(uuid, uuid) to authenticated;
grant execute on function public.campaign_party(uuid) to authenticated;
grant execute on function public.delete_my_account() to authenticated;

-- =====================================================================
-- 0007_spells.sql
-- =====================================================================

-- 0007: spells with drafts and frozen versions, effect presets, and
-- spells on characters.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

create table if not exists public.spells (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists spells_owner_idx on public.spells (owner_id);

create table if not exists public.spell_versions (
  id uuid primary key default gen_random_uuid(),
  spell_id uuid not null references public.spells (id) on delete cascade,
  status text not null check (status in ('draft', 'published')),
  version_number integer,
  content jsonb not null
    check (jsonb_typeof(content) = 'object' and octet_length(content::text) < 131072),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz,
  check (
    (status = 'draft' and version_number is null and published_at is null)
    or (status = 'published' and version_number >= 1 and published_at is not null)
  ),
  unique (spell_id, version_number)
);
create unique index if not exists spell_versions_one_draft
  on public.spell_versions (spell_id) where status = 'draft';

create table if not exists public.effect_presets (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 60),
  effect jsonb not null check (jsonb_typeof(effect) = 'object' and octet_length(effect::text) < 8192),
  created_at timestamptz not null default now()
);
create index if not exists effect_presets_owner_idx on public.effect_presets (owner_id);

create table if not exists public.character_spells (
  character_id uuid not null references public.characters (id) on delete cascade,
  -- No "on delete" rule: a spell version in use can't be deleted.
  spell_version_id uuid not null references public.spell_versions (id),
  known boolean not null default true,
  prepared boolean not null default false,
  added_at timestamptz not null default now(),
  primary key (character_id, spell_version_id)
);
create index if not exists character_spells_version_idx on public.character_spells (spell_version_id);

alter table public.spells enable row level security;
alter table public.spell_versions enable row level security;
alter table public.effect_presets enable row level security;
alter table public.character_spells enable row level security;
revoke all on public.spells from anon, authenticated;
revoke all on public.spell_versions from anon, authenticated;
revoke all on public.effect_presets from anon, authenticated;
revoke all on public.character_spells from anon, authenticated;

-- Published spell versions are frozen forever.
create or replace function public.spell_versions_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.status = 'published' then
    raise exception 'version_published';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists spell_versions_guard on public.spell_versions;
create trigger spell_versions_guard
  before update on public.spell_versions
  for each row execute function public.spell_versions_guard();

create or replace function public.owns_spell(p_spell uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.spells where id = p_spell and owner_id = auth.uid());
$$;

-- Readable by the owner, and by anyone who can see a character that has it.
-- (Phase 5b adds spells approved for a campaign.)
create or replace function public.can_read_spell_version(p_version uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.spell_versions v
    join public.spells s on s.id = v.spell_id
    where v.id = p_version and s.owner_id = auth.uid()
  ) or exists (
    select 1 from public.character_spells cs
    where cs.spell_version_id = p_version and public.can_view_character(cs.character_id)
  );
$$;

create or replace function public.can_read_spell(p_spell uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.spell_versions v
    where v.spell_id = p_spell and v.status = 'published' and public.can_read_spell_version(v.id)
  );
$$;

-- Which spell versions may go on a character: your own published ones.
create or replace function public.can_use_spell_version(p_version uuid, p_character uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.spell_versions v
    join public.spells s on s.id = v.spell_id
    where v.id = p_version and v.status = 'published' and s.owner_id = auth.uid()
  );
$$;

revoke execute on function public.owns_spell(uuid) from public, anon;
revoke execute on function public.can_read_spell_version(uuid) from public, anon;
revoke execute on function public.can_read_spell(uuid) from public, anon;
revoke execute on function public.can_use_spell_version(uuid, uuid) from public, anon;
grant execute on function public.owns_spell(uuid) to authenticated;
grant execute on function public.can_read_spell_version(uuid) to authenticated;
grant execute on function public.can_read_spell(uuid) to authenticated;
grant execute on function public.can_use_spell_version(uuid, uuid) to authenticated;

grant select on public.spells to authenticated;
grant update (name) on public.spells to authenticated;

drop policy if exists "Readable spells" on public.spells;
create policy "Readable spells"
  on public.spells for select to authenticated
  using (owner_id = (select auth.uid()) or public.can_read_spell(id));

drop policy if exists "Owners rename spells" on public.spells;
create policy "Owners rename spells"
  on public.spells for update to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

grant select on public.spell_versions to authenticated;
grant update (content) on public.spell_versions to authenticated;

drop policy if exists "Readable spell versions" on public.spell_versions;
create policy "Readable spell versions"
  on public.spell_versions for select to authenticated
  using (public.owns_spell(spell_id) or (status = 'published' and public.can_read_spell_version(id)));

drop policy if exists "Owners edit spell drafts" on public.spell_versions;
create policy "Owners edit spell drafts"
  on public.spell_versions for update to authenticated
  using (status = 'draft' and public.owns_spell(spell_id))
  with check (status = 'draft' and public.owns_spell(spell_id));

grant select, insert (name, effect), delete on public.effect_presets to authenticated;

drop policy if exists "Owners use presets" on public.effect_presets;
create policy "Owners use presets"
  on public.effect_presets for select to authenticated
  using (owner_id = (select auth.uid()));

drop policy if exists "Owners add presets" on public.effect_presets;
create policy "Owners add presets"
  on public.effect_presets for insert to authenticated
  with check (owner_id = (select auth.uid()));

drop policy if exists "Owners remove presets" on public.effect_presets;
create policy "Owners remove presets"
  on public.effect_presets for delete to authenticated
  using (owner_id = (select auth.uid()));

grant select, delete on public.character_spells to authenticated;
grant update (known, prepared) on public.character_spells to authenticated;

drop policy if exists "Character spells visible with the character" on public.character_spells;
create policy "Character spells visible with the character"
  on public.character_spells for select to authenticated
  using (public.can_view_character(character_id));

drop policy if exists "Owners mark character spells" on public.character_spells;
create policy "Owners mark character spells"
  on public.character_spells for update to authenticated
  using (public.owns_character(character_id))
  with check (public.owns_character(character_id));

drop policy if exists "Owners remove character spells" on public.character_spells;
create policy "Owners remove character spells"
  on public.character_spells for delete to authenticated
  using (public.owns_character(character_id));

-- ---------------------------------------------------------------
-- Actions
-- ---------------------------------------------------------------
create or replace function public.create_spell(p_name text, p_content jsonb)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_signed_in'; end if;
  insert into public.spells (owner_id, name) values (auth.uid(), trim(p_name)) returning id into v_id;
  insert into public.spell_versions (spell_id, status, content) values (v_id, 'draft', p_content);
  return v_id;
end;
$$;

create or replace function public.publish_spell(p_spell uuid)
returns integer
language plpgsql security definer set search_path = ''
as $$
declare
  v_draft uuid;
  v_next integer;
begin
  if not public.owns_spell(p_spell) then raise exception 'not_allowed'; end if;
  select id into v_draft from public.spell_versions
  where spell_id = p_spell and status = 'draft' for update;
  if v_draft is null then raise exception 'no_draft'; end if;
  select coalesce(max(version_number), 0) + 1 into v_next
  from public.spell_versions where spell_id = p_spell and status = 'published';
  update public.spell_versions
  set status = 'published', version_number = v_next, published_at = now()
  where id = v_draft;
  update public.spells set updated_at = now() where id = p_spell;
  return v_next;
end;
$$;

create or replace function public.start_spell_draft(p_spell uuid)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_draft uuid;
  v_content jsonb;
begin
  if not public.owns_spell(p_spell) then raise exception 'not_allowed'; end if;
  select id into v_draft from public.spell_versions where spell_id = p_spell and status = 'draft';
  if v_draft is not null then return v_draft; end if;
  select content into v_content from public.spell_versions
  where spell_id = p_spell and status = 'published'
  order by version_number desc limit 1;
  if v_content is null then raise exception 'no_versions'; end if;
  insert into public.spell_versions (spell_id, status, content)
  values (p_spell, 'draft', v_content) returning id into v_draft;
  return v_draft;
end;
$$;

create or replace function public.discard_spell_draft(p_spell uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.owns_spell(p_spell) then raise exception 'not_allowed'; end if;
  if not exists (select 1 from public.spell_versions where spell_id = p_spell and status = 'published') then
    raise exception 'only_draft';
  end if;
  delete from public.spell_versions where spell_id = p_spell and status = 'draft';
end;
$$;

create or replace function public.duplicate_spell(p_spell uuid)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_name text;
  v_content jsonb;
  v_id uuid;
begin
  if not public.owns_spell(p_spell) then raise exception 'not_allowed'; end if;
  select name into v_name from public.spells where id = p_spell;
  select content into v_content from public.spell_versions
  where spell_id = p_spell
  order by (status = 'draft') desc, version_number desc nulls last limit 1;
  insert into public.spells (owner_id, name) values (auth.uid(), left('Copy of ' || v_name, 80))
  returning id into v_id;
  insert into public.spell_versions (spell_id, status, content) values (v_id, 'draft', v_content);
  return v_id;
end;
$$;

create or replace function public.delete_spell(p_spell uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.owns_spell(p_spell) then raise exception 'not_allowed'; end if;
  if exists (
    select 1 from public.character_spells cs
    join public.spell_versions v on v.id = cs.spell_version_id
    where v.spell_id = p_spell
  ) then
    raise exception 'spell_in_use';
  end if;
  delete from public.spells where id = p_spell;
end;
$$;

create or replace function public.add_spell_to_character(p_character uuid, p_version uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.owns_character(p_character) then raise exception 'not_allowed'; end if;
  if exists (select 1 from public.spell_versions where id = p_version and status = 'draft') then
    raise exception 'not_published';
  end if;
  if not public.can_use_spell_version(p_version, p_character) then raise exception 'spell_not_allowed'; end if;
  insert into public.character_spells (character_id, spell_version_id)
  values (p_character, p_version)
  on conflict do nothing;
end;
$$;

-- Accounts can't be deleted while other players' characters use their spells.
create or replace function public.delete_my_account()
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  if exists (select 1 from public.campaign_members
             where user_id = auth.uid() and role = 'owner') then
    raise exception 'owns_campaigns';
  end if;
  if exists (
    select 1 from public.characters ch
    join public.sheet_template_versions v on v.id = ch.template_version_id
    join public.sheet_templates t on t.id = v.template_id
    where t.owner_id = auth.uid() and ch.owner_id <> auth.uid()
  ) or exists (
    select 1 from public.character_spells cs
    join public.characters ch on ch.id = cs.character_id
    join public.spell_versions v on v.id = cs.spell_version_id
    join public.spells s on s.id = v.spell_id
    where s.owner_id = auth.uid() and ch.owner_id <> auth.uid()
  ) then
    raise exception 'templates_in_use';
  end if;
  delete from auth.users where id = auth.uid();
end;
$$;

revoke execute on function public.create_spell(text, jsonb) from public, anon;
revoke execute on function public.publish_spell(uuid) from public, anon;
revoke execute on function public.start_spell_draft(uuid) from public, anon;
revoke execute on function public.discard_spell_draft(uuid) from public, anon;
revoke execute on function public.duplicate_spell(uuid) from public, anon;
revoke execute on function public.delete_spell(uuid) from public, anon;
revoke execute on function public.add_spell_to_character(uuid, uuid) from public, anon;
revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.create_spell(text, jsonb) to authenticated;
grant execute on function public.publish_spell(uuid) to authenticated;
grant execute on function public.start_spell_draft(uuid) to authenticated;
grant execute on function public.discard_spell_draft(uuid) to authenticated;
grant execute on function public.duplicate_spell(uuid) to authenticated;
grant execute on function public.delete_spell(uuid) to authenticated;
grant execute on function public.add_spell_to_character(uuid, uuid) to authenticated;
grant execute on function public.delete_my_account() to authenticated;

-- =====================================================================
-- 0008_homebrew.sql
-- =====================================================================

-- 0008: homebrew submissions, the DM approval queue, campaign spell lists,
-- and the "approved spells only" rule for characters in campaigns.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

alter table public.campaigns
  add column if not exists spells_need_approval boolean not null default true;
grant update (spells_need_approval) on public.campaigns to authenticated;

create table if not exists public.campaign_spells (
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  spell_version_id uuid not null references public.spell_versions (id) on delete cascade,
  added_by uuid references auth.users (id) on delete set null,
  added_at timestamptz not null default now(),
  primary key (campaign_id, spell_version_id)
);

create table if not exists public.homebrew_submissions (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  content_type text not null check (content_type in ('spell', 'template')),
  spell_version_id uuid references public.spell_versions (id) on delete cascade,
  template_version_id uuid references public.sheet_template_versions (id) on delete cascade,
  submitted_by uuid not null references auth.users (id) on delete cascade,
  submitter_note text not null default '' check (char_length(submitter_note) <= 500),
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected', 'changes_requested')),
  review_note text not null default '' check (char_length(review_note) <= 1000),
  reviewed_by uuid references auth.users (id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  check (
    (content_type = 'spell' and spell_version_id is not null and template_version_id is null)
    or (content_type = 'template' and template_version_id is not null and spell_version_id is null)
  )
);
create index if not exists homebrew_submissions_campaign_idx
  on public.homebrew_submissions (campaign_id, status, created_at desc);
create unique index if not exists homebrew_one_pending_spell
  on public.homebrew_submissions (campaign_id, spell_version_id) where status = 'pending';
create unique index if not exists homebrew_one_pending_template
  on public.homebrew_submissions (campaign_id, template_version_id) where status = 'pending';

alter table public.campaign_spells enable row level security;
alter table public.homebrew_submissions enable row level security;
revoke all on public.campaign_spells from anon, authenticated;
revoke all on public.homebrew_submissions from anon, authenticated;

grant select on public.campaign_spells to authenticated;
drop policy if exists "Members see campaign spells" on public.campaign_spells;
create policy "Members see campaign spells"
  on public.campaign_spells for select to authenticated
  using (public.is_campaign_member(campaign_id));

grant select on public.homebrew_submissions to authenticated;
drop policy if exists "Submitters and managers see submissions" on public.homebrew_submissions;
create policy "Submitters and managers see submissions"
  on public.homebrew_submissions for select to authenticated
  using (submitted_by = (select auth.uid()) or public.is_campaign_manager(campaign_id));

-- ---------------------------------------------------------------
-- Reading rules, extended
-- ---------------------------------------------------------------

-- Spells: owner; anyone who can see a character that has it; members of a
-- campaign where it's approved; managers reviewing a submission of it.
create or replace function public.can_read_spell_version(p_version uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.spell_versions v
    join public.spells s on s.id = v.spell_id
    where v.id = p_version and s.owner_id = auth.uid()
  ) or exists (
    select 1 from public.character_spells cs
    where cs.spell_version_id = p_version and public.can_view_character(cs.character_id)
  ) or exists (
    select 1 from public.campaign_spells cs
    where cs.spell_version_id = p_version and public.is_campaign_member(cs.campaign_id)
  ) or exists (
    select 1 from public.homebrew_submissions h
    where h.spell_version_id = p_version and public.is_campaign_manager(h.campaign_id)
  );
$$;

-- Templates: as before, plus managers reviewing a submission.
create or replace function public.can_read_template_version(p_version uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.sheet_template_versions v
    join public.sheet_templates t on t.id = v.template_id
    where v.id = p_version and t.owner_id = auth.uid()
  ) or exists (
    select 1 from public.campaign_templates ct
    where ct.template_version_id = p_version and public.is_campaign_member(ct.campaign_id)
  ) or exists (
    select 1 from public.characters ch
    where ch.template_version_id = p_version and public.can_view_character(ch.id)
  ) or exists (
    select 1 from public.homebrew_submissions h
    where h.template_version_id = p_version and public.is_campaign_manager(h.campaign_id)
  );
$$;

-- Which spells may go on a character. Outside a campaign: your own
-- published spells. Inside one: spells the campaign approved, plus your own
-- if the campaign doesn't require approval.
create or replace function public.can_use_spell_version(p_version uuid, p_character uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  with own as (
    select exists (
      select 1 from public.spell_versions v
      join public.spells s on s.id = v.spell_id
      where v.id = p_version and v.status = 'published' and s.owner_id = auth.uid()
    ) as ok
  ),
  membership as (
    select cc.campaign_id, c.spells_need_approval
    from public.campaign_characters cc
    join public.campaigns c on c.id = cc.campaign_id
    where cc.character_id = p_character
  )
  select case
    when not exists (select 1 from membership) then (select ok from own)
    else exists (
      select 1 from public.campaign_spells cs, membership m
      where cs.campaign_id = m.campaign_id and cs.spell_version_id = p_version
    ) or ((select ok from own) and not (select spells_need_approval from membership))
  end;
$$;

-- ---------------------------------------------------------------
-- Actions
-- ---------------------------------------------------------------
create or replace function public.submit_homebrew(
  p_campaign uuid, p_type text, p_version uuid, p_note text default ''
)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_campaign_member(p_campaign) then raise exception 'not_allowed'; end if;

  if p_type = 'spell' then
    if not exists (
      select 1 from public.spell_versions v join public.spells s on s.id = v.spell_id
      where v.id = p_version and v.status = 'published' and s.owner_id = auth.uid()
    ) then raise exception 'not_your_content'; end if;
    if exists (select 1 from public.campaign_spells
               where campaign_id = p_campaign and spell_version_id = p_version) then
      raise exception 'already_approved';
    end if;
    if exists (select 1 from public.homebrew_submissions
               where campaign_id = p_campaign and spell_version_id = p_version and status = 'pending') then
      raise exception 'already_pending';
    end if;
    insert into public.homebrew_submissions (campaign_id, content_type, spell_version_id, submitted_by, submitter_note)
    values (p_campaign, 'spell', p_version, auth.uid(), left(coalesce(p_note, ''), 500))
    returning id into v_id;
  elsif p_type = 'template' then
    if not exists (
      select 1 from public.sheet_template_versions v join public.sheet_templates t on t.id = v.template_id
      where v.id = p_version and v.status = 'published' and t.owner_id = auth.uid()
    ) then raise exception 'not_your_content'; end if;
    if exists (select 1 from public.campaign_templates
               where campaign_id = p_campaign and template_version_id = p_version) then
      raise exception 'already_approved';
    end if;
    if exists (select 1 from public.homebrew_submissions
               where campaign_id = p_campaign and template_version_id = p_version and status = 'pending') then
      raise exception 'already_pending';
    end if;
    insert into public.homebrew_submissions (campaign_id, content_type, template_version_id, submitted_by, submitter_note)
    values (p_campaign, 'template', p_version, auth.uid(), left(coalesce(p_note, ''), 500))
    returning id into v_id;
  else
    raise exception 'invalid_input';
  end if;
  return v_id;
end;
$$;

create or replace function public.withdraw_submission(p_submission uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not exists (select 1 from public.homebrew_submissions
                 where id = p_submission and submitted_by = auth.uid()) then
    raise exception 'not_allowed';
  end if;
  delete from public.homebrew_submissions where id = p_submission and status = 'pending';
end;
$$;

create or replace function public.review_submission(p_submission uuid, p_decision text, p_note text default '')
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v public.homebrew_submissions;
begin
  select * into v from public.homebrew_submissions where id = p_submission for update;
  if v.id is null or not public.is_campaign_manager(v.campaign_id) then raise exception 'not_allowed'; end if;
  if v.status <> 'pending' then raise exception 'already_reviewed'; end if;
  if p_decision not in ('approved', 'rejected', 'changes_requested') then raise exception 'invalid_input'; end if;

  update public.homebrew_submissions
  set status = p_decision, review_note = left(coalesce(p_note, ''), 1000),
      reviewed_by = auth.uid(), reviewed_at = now()
  where id = p_submission;

  if p_decision = 'approved' then
    if v.content_type = 'spell' then
      insert into public.campaign_spells (campaign_id, spell_version_id, added_by)
      values (v.campaign_id, v.spell_version_id, auth.uid()) on conflict do nothing;
    else
      insert into public.campaign_templates (campaign_id, template_version_id, added_by)
      values (v.campaign_id, v.template_version_id, auth.uid()) on conflict do nothing;
    end if;
  end if;
end;
$$;

-- DMs add their own published spells without going through the queue.
create or replace function public.add_spell_to_campaign(p_campaign uuid, p_version uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.is_campaign_manager(p_campaign) then raise exception 'not_allowed'; end if;
  if not exists (
    select 1 from public.spell_versions v join public.spells s on s.id = v.spell_id
    where v.id = p_version and v.status = 'published' and s.owner_id = auth.uid()
  ) then raise exception 'not_your_content'; end if;
  insert into public.campaign_spells (campaign_id, spell_version_id, added_by)
  values (p_campaign, p_version, auth.uid()) on conflict do nothing;
end;
$$;

-- Removing a spell from the list doesn't take it off characters that have it.
create or replace function public.remove_spell_from_campaign(p_campaign uuid, p_version uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if not public.is_campaign_manager(p_campaign) then raise exception 'not_allowed'; end if;
  delete from public.campaign_spells where campaign_id = p_campaign and spell_version_id = p_version;
end;
$$;

revoke execute on function public.submit_homebrew(uuid, text, uuid, text) from public, anon;
revoke execute on function public.withdraw_submission(uuid) from public, anon;
revoke execute on function public.review_submission(uuid, text, text) from public, anon;
revoke execute on function public.add_spell_to_campaign(uuid, uuid) from public, anon;
revoke execute on function public.remove_spell_from_campaign(uuid, uuid) from public, anon;
grant execute on function public.submit_homebrew(uuid, text, uuid, text) to authenticated;
grant execute on function public.withdraw_submission(uuid) to authenticated;
grant execute on function public.review_submission(uuid, text, text) to authenticated;
grant execute on function public.add_spell_to_campaign(uuid, uuid) to authenticated;
grant execute on function public.remove_spell_from_campaign(uuid, uuid) to authenticated;

-- =====================================================================
-- 0009_campaign_tools.sql
-- =====================================================================

-- 0009: announcements, session logs, private DM notes and the activity log.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

alter table public.campaigns
  add column if not exists players_write_logs boolean not null default false;
grant update (players_write_logs) on public.campaigns to authenticated;

create table if not exists public.announcements (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  author_id uuid default auth.uid() references auth.users (id) on delete set null,
  title text not null check (char_length(title) between 1 and 120),
  body text not null default '' check (char_length(body) <= 5000),
  pinned boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists announcements_campaign_idx on public.announcements (campaign_id, pinned desc, created_at desc);

create table if not exists public.session_logs (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  author_id uuid default auth.uid() references auth.users (id) on delete set null,
  session_number integer check (session_number is null or session_number between 0 and 10000),
  played_on date,
  title text not null check (char_length(title) between 1 and 120),
  body text not null default '' check (char_length(body) <= 20000),
  visibility text not null default 'players' check (visibility in ('players', 'dm_only')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists session_logs_campaign_idx on public.session_logs (campaign_id, session_number desc, created_at desc);

-- DM notes live in their own table so nothing players can read ever touches them.
create table if not exists public.dm_notes (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  author_id uuid default auth.uid() references auth.users (id) on delete set null,
  title text not null check (char_length(title) between 1 and 120),
  body text not null default '' check (char_length(body) <= 20000),
  character_id uuid references public.characters (id) on delete set null,
  session_log_id uuid references public.session_logs (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists dm_notes_campaign_idx on public.dm_notes (campaign_id, updated_at desc);

create table if not exists public.audit_log (
  id bigint generated always as identity primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  actor_id uuid references auth.users (id) on delete set null,
  action text not null,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists audit_log_campaign_idx on public.audit_log (campaign_id, created_at desc);

alter table public.announcements enable row level security;
alter table public.session_logs enable row level security;
alter table public.dm_notes enable row level security;
alter table public.audit_log enable row level security;
revoke all on public.announcements from anon, authenticated;
revoke all on public.session_logs from anon, authenticated;
revoke all on public.dm_notes from anon, authenticated;
revoke all on public.audit_log from anon, authenticated;

-- Keep "updated" times fresh.
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists announcements_touch on public.announcements;
create trigger announcements_touch before update on public.announcements
  for each row execute function public.touch_updated_at();
drop trigger if exists session_logs_touch on public.session_logs;
create trigger session_logs_touch before update on public.session_logs
  for each row execute function public.touch_updated_at();
drop trigger if exists dm_notes_touch on public.dm_notes;
create trigger dm_notes_touch before update on public.dm_notes
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------
-- Announcements: members read; DMs and Co-DMs write.
-- ---------------------------------------------------------------
grant select, delete on public.announcements to authenticated;
grant insert (campaign_id, title, body, pinned) on public.announcements to authenticated;
grant update (title, body, pinned) on public.announcements to authenticated;

drop policy if exists "Members read announcements" on public.announcements;
create policy "Members read announcements" on public.announcements for select to authenticated
  using (public.is_campaign_member(campaign_id));
drop policy if exists "Managers post announcements" on public.announcements;
create policy "Managers post announcements" on public.announcements for insert to authenticated
  with check (public.is_campaign_manager(campaign_id) and author_id = (select auth.uid()));
drop policy if exists "Managers edit announcements" on public.announcements;
create policy "Managers edit announcements" on public.announcements for update to authenticated
  using (public.is_campaign_manager(campaign_id)) with check (public.is_campaign_manager(campaign_id));
drop policy if exists "Managers delete announcements" on public.announcements;
create policy "Managers delete announcements" on public.announcements for delete to authenticated
  using (public.is_campaign_manager(campaign_id));

-- ---------------------------------------------------------------
-- Session logs: DM-only logs are visible to managers only. Players may
-- write player-visible logs when the campaign allows it.
-- ---------------------------------------------------------------
create or replace function public.players_may_write_logs(p_campaign uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce((select players_write_logs from public.campaigns where id = p_campaign), false)
    and public.is_campaign_member(p_campaign);
$$;
revoke execute on function public.players_may_write_logs(uuid) from public, anon;
grant execute on function public.players_may_write_logs(uuid) to authenticated;

grant select, delete on public.session_logs to authenticated;
grant insert (campaign_id, session_number, played_on, title, body, visibility) on public.session_logs to authenticated;
grant update (session_number, played_on, title, body, visibility) on public.session_logs to authenticated;

drop policy if exists "Read session logs" on public.session_logs;
create policy "Read session logs" on public.session_logs for select to authenticated
  using (
    public.is_campaign_manager(campaign_id)
    or (visibility = 'players' and public.is_campaign_member(campaign_id))
  );
drop policy if exists "Write session logs" on public.session_logs;
create policy "Write session logs" on public.session_logs for insert to authenticated
  with check (
    author_id = (select auth.uid())
    and (
      public.is_campaign_manager(campaign_id)
      or (visibility = 'players' and public.players_may_write_logs(campaign_id))
    )
  );
drop policy if exists "Edit session logs" on public.session_logs;
create policy "Edit session logs" on public.session_logs for update to authenticated
  using (
    public.is_campaign_manager(campaign_id)
    or (author_id = (select auth.uid()) and visibility = 'players' and public.players_may_write_logs(campaign_id))
  )
  with check (
    public.is_campaign_manager(campaign_id)
    or (author_id = (select auth.uid()) and visibility = 'players' and public.players_may_write_logs(campaign_id))
  );
drop policy if exists "Delete session logs" on public.session_logs;
create policy "Delete session logs" on public.session_logs for delete to authenticated
  using (
    public.is_campaign_manager(campaign_id)
    or (author_id = (select auth.uid()) and visibility = 'players')
  );

-- ---------------------------------------------------------------
-- DM notes: managers only, for every operation. Links must point at
-- characters and logs from the same campaign.
-- ---------------------------------------------------------------
grant select, delete on public.dm_notes to authenticated;
grant insert (campaign_id, title, body, character_id, session_log_id) on public.dm_notes to authenticated;
grant update (title, body, character_id, session_log_id) on public.dm_notes to authenticated;

create or replace function public.dm_note_links_ok(p_campaign uuid, p_character uuid, p_log uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select (p_character is null or exists (
            select 1 from public.campaign_characters
            where campaign_id = p_campaign and character_id = p_character))
     and (p_log is null or exists (
            select 1 from public.session_logs where id = p_log and campaign_id = p_campaign));
$$;
revoke execute on function public.dm_note_links_ok(uuid, uuid, uuid) from public, anon;
grant execute on function public.dm_note_links_ok(uuid, uuid, uuid) to authenticated;

drop policy if exists "Managers read DM notes" on public.dm_notes;
create policy "Managers read DM notes" on public.dm_notes for select to authenticated
  using (public.is_campaign_manager(campaign_id));
drop policy if exists "Managers write DM notes" on public.dm_notes;
create policy "Managers write DM notes" on public.dm_notes for insert to authenticated
  with check (
    public.is_campaign_manager(campaign_id)
    and author_id = (select auth.uid())
    and public.dm_note_links_ok(campaign_id, character_id, session_log_id)
  );
drop policy if exists "Managers edit DM notes" on public.dm_notes;
create policy "Managers edit DM notes" on public.dm_notes for update to authenticated
  using (public.is_campaign_manager(campaign_id))
  with check (
    public.is_campaign_manager(campaign_id)
    and public.dm_note_links_ok(campaign_id, character_id, session_log_id)
  );
drop policy if exists "Managers delete DM notes" on public.dm_notes;
create policy "Managers delete DM notes" on public.dm_notes for delete to authenticated
  using (public.is_campaign_manager(campaign_id));

-- ---------------------------------------------------------------
-- Activity log: written only by the triggers below, read by managers.
-- ---------------------------------------------------------------
grant select on public.audit_log to authenticated;
drop policy if exists "Managers read the activity log" on public.audit_log;
create policy "Managers read the activity log" on public.audit_log for select to authenticated
  using (public.is_campaign_manager(campaign_id));

create or replace function public.log_activity(p_campaign uuid, p_action text, p_details jsonb)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  -- Skip when the campaign itself is being deleted.
  if exists (select 1 from public.campaigns where id = p_campaign) then
    insert into public.audit_log (campaign_id, actor_id, action, details)
    values (p_campaign, auth.uid(), p_action, coalesce(p_details, '{}'::jsonb));
  end if;
end;
$$;
revoke execute on function public.log_activity(uuid, text, jsonb) from public, anon, authenticated;

create or replace function public.audit_campaign_members()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform public.log_activity(new.campaign_id, 'member_joined',
      jsonb_build_object('user_id', new.user_id, 'role', new.role));
  elsif tg_op = 'UPDATE' and new.role is distinct from old.role then
    perform public.log_activity(new.campaign_id, 'role_changed',
      jsonb_build_object('user_id', new.user_id, 'from', old.role, 'to', new.role));
  elsif tg_op = 'DELETE' then
    perform public.log_activity(old.campaign_id,
      case when old.user_id = auth.uid() then 'member_left' else 'member_removed' end,
      jsonb_build_object('user_id', old.user_id));
  end if;
  return null;
end;
$$;
drop trigger if exists audit_campaign_members on public.campaign_members;
create trigger audit_campaign_members after insert or update or delete on public.campaign_members
  for each row execute function public.audit_campaign_members();

create or replace function public.audit_campaigns()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if new.name is distinct from old.name then
    perform public.log_activity(new.id, 'campaign_renamed', jsonb_build_object('from', old.name, 'to', new.name));
  end if;
  if new.status is distinct from old.status then
    perform public.log_activity(new.id, case when new.status = 'archived' then 'campaign_archived' else 'campaign_restored' end, '{}'::jsonb);
  end if;
  if new.players_see_full_sheets is distinct from old.players_see_full_sheets then
    perform public.log_activity(new.id, 'setting_changed', jsonb_build_object('setting', 'players_see_full_sheets', 'value', new.players_see_full_sheets));
  end if;
  if new.spells_need_approval is distinct from old.spells_need_approval then
    perform public.log_activity(new.id, 'setting_changed', jsonb_build_object('setting', 'spells_need_approval', 'value', new.spells_need_approval));
  end if;
  if new.players_write_logs is distinct from old.players_write_logs then
    perform public.log_activity(new.id, 'setting_changed', jsonb_build_object('setting', 'players_write_logs', 'value', new.players_write_logs));
  end if;
  return null;
end;
$$;
drop trigger if exists audit_campaigns on public.campaigns;
create trigger audit_campaigns after update on public.campaigns
  for each row execute function public.audit_campaigns();

create or replace function public.audit_submissions()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if new.status is distinct from old.status and new.status <> 'pending' then
    perform public.log_activity(new.campaign_id, 'submission_reviewed',
      jsonb_build_object('submission_id', new.id, 'type', new.content_type, 'decision', new.status, 'user_id', new.submitted_by));
  end if;
  return null;
end;
$$;
drop trigger if exists audit_submissions on public.homebrew_submissions;
create trigger audit_submissions after update on public.homebrew_submissions
  for each row execute function public.audit_submissions();

create or replace function public.audit_invites()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform public.log_activity(new.campaign_id, 'invite_created', jsonb_build_object('max_uses', new.max_uses));
  elsif new.revoked_at is not null and old.revoked_at is null then
    perform public.log_activity(new.campaign_id, 'invite_cancelled', '{}'::jsonb);
  end if;
  return null;
end;
$$;
drop trigger if exists audit_invites on public.campaign_invites;
create trigger audit_invites after insert or update on public.campaign_invites
  for each row execute function public.audit_invites();

create or replace function public.audit_campaign_content()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_campaign uuid := coalesce(new.campaign_id, old.campaign_id);
begin
  if tg_table_name = 'campaign_spells' then
    perform public.log_activity(v_campaign, case when tg_op = 'INSERT' then 'spell_added' else 'spell_removed' end,
      jsonb_build_object('version_id', coalesce(new.spell_version_id, old.spell_version_id)));
  elsif tg_table_name = 'campaign_templates' then
    perform public.log_activity(v_campaign, case when tg_op = 'INSERT' then 'template_offered' else 'template_withdrawn' end,
      jsonb_build_object('version_id', coalesce(new.template_version_id, old.template_version_id)));
  elsif tg_table_name = 'session_logs' and tg_op = 'DELETE' then
    perform public.log_activity(v_campaign, 'log_deleted', jsonb_build_object('title', old.title));
  elsif tg_table_name = 'announcements' and tg_op = 'DELETE' then
    perform public.log_activity(v_campaign, 'announcement_deleted', jsonb_build_object('title', old.title));
  end if;
  return null;
end;
$$;
drop trigger if exists audit_campaign_spells on public.campaign_spells;
create trigger audit_campaign_spells after insert or delete on public.campaign_spells
  for each row execute function public.audit_campaign_content();
drop trigger if exists audit_campaign_templates on public.campaign_templates;
create trigger audit_campaign_templates after insert or delete on public.campaign_templates
  for each row execute function public.audit_campaign_content();
drop trigger if exists audit_session_logs on public.session_logs;
create trigger audit_session_logs after delete on public.session_logs
  for each row execute function public.audit_campaign_content();
drop trigger if exists audit_announcements on public.announcements;
create trigger audit_announcements after delete on public.announcements
  for each row execute function public.audit_campaign_content();

-- =====================================================================
-- 0010_chat_handouts.sql
-- =====================================================================

-- 0010: live campaign chat with whispers, and handouts with private files.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

-- ---------------------------------------------------------------
-- Chat
-- ---------------------------------------------------------------
create table if not exists public.messages (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  author_id uuid default auth.uid() references auth.users (id) on delete set null,
  body text not null check (char_length(body) between 1 and 2000),
  -- null = everyone in the campaign; otherwise a whisper to these people
  recipients uuid[] check (recipients is null or (cardinality(recipients) between 1 and 50)),
  created_at timestamptz not null default now(),
  edited_at timestamptz
);
create index if not exists messages_campaign_idx on public.messages (campaign_id, created_at desc);
create index if not exists messages_author_recent_idx on public.messages (author_id, created_at desc);

alter table public.messages enable row level security;
revoke all on public.messages from anon, authenticated;

-- Whisper rule: DMs and Co-DMs may whisper to any members; players may only
-- whisper to DMs and Co-DMs. Everyone must be in the campaign.
create or replace function public.whisper_allowed(p_campaign uuid, p_recipients uuid[])
returns boolean
language sql stable security definer set search_path = ''
as $$
  select p_recipients is null
    or (
      not exists (
        select 1 from unnest(p_recipients) r(id)
        where not exists (
          select 1 from public.campaign_members m
          where m.campaign_id = p_campaign and m.user_id = r.id
            and (public.is_campaign_manager(p_campaign) or m.role in ('owner', 'co_dm'))
        )
      )
    );
$$;

create or replace function public.can_read_message(p_campaign uuid, p_author uuid, p_recipients uuid[])
returns boolean
language sql stable security definer set search_path = ''
as $$
  select public.is_campaign_member(p_campaign)
    and (
      p_recipients is null
      or p_author = auth.uid()
      or auth.uid() = any (p_recipients)
      or public.is_campaign_manager(p_campaign)
    );
$$;

revoke execute on function public.whisper_allowed(uuid, uuid[]) from public, anon;
revoke execute on function public.can_read_message(uuid, uuid, uuid[]) from public, anon;
grant execute on function public.whisper_allowed(uuid, uuid[]) to authenticated;
grant execute on function public.can_read_message(uuid, uuid, uuid[]) to authenticated;

grant select, delete on public.messages to authenticated;
grant insert (campaign_id, body, recipients) on public.messages to authenticated;
grant update (body) on public.messages to authenticated;

drop policy if exists "Read messages" on public.messages;
create policy "Read messages" on public.messages for select to authenticated
  using (public.can_read_message(campaign_id, author_id, recipients));
drop policy if exists "Send messages" on public.messages;
create policy "Send messages" on public.messages for insert to authenticated
  with check (
    author_id = (select auth.uid())
    and public.is_campaign_member(campaign_id)
    and public.whisper_allowed(campaign_id, recipients)
  );
drop policy if exists "Edit own messages" on public.messages;
create policy "Edit own messages" on public.messages for update to authenticated
  using (author_id = (select auth.uid())) with check (author_id = (select auth.uid()));
drop policy if exists "Delete messages" on public.messages;
create policy "Delete messages" on public.messages for delete to authenticated
  using (author_id = (select auth.uid()) or public.is_campaign_manager(campaign_id));

-- Spam guard and "edited" marker.
create or replace function public.messages_before_write()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if (select count(*) from public.messages
        where author_id = new.author_id and created_at > now() - interval '10 seconds') >= 10 then
      raise exception 'slow_down';
    end if;
  elsif new.body is distinct from old.body then
    new.edited_at := now();
  end if;
  return new;
end;
$$;
drop trigger if exists messages_before_write on public.messages;
create trigger messages_before_write before insert or update on public.messages
  for each row execute function public.messages_before_write();

-- A DM deleting someone else's message is recorded in the activity log.
create or replace function public.audit_message_delete()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if old.author_id is distinct from auth.uid() then
    perform public.log_activity(old.campaign_id, 'message_deleted', jsonb_build_object('user_id', old.author_id));
  end if;
  return null;
end;
$$;
drop trigger if exists audit_message_delete on public.messages;
create trigger audit_message_delete after delete on public.messages
  for each row execute function public.audit_message_delete();

-- Live updates for chat (respects the read rules above).
do $$ begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'messages'
  ) then
    alter publication supabase_realtime add table public.messages;
  end if;
end $$;

-- ---------------------------------------------------------------
-- Handouts
-- ---------------------------------------------------------------
create table if not exists public.handouts (
  id uuid primary key,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  author_id uuid default auth.uid() references auth.users (id) on delete set null,
  title text not null check (char_length(title) between 1 and 120),
  body text not null default '' check (char_length(body) <= 10000),
  visibility text not null default 'all' check (visibility in ('all', 'selected', 'dm_only')),
  file_path text check (file_path is null or file_path like campaign_id::text || '/' || id::text || '/%'),
  file_name text check (file_name is null or char_length(file_name) <= 200),
  file_type text check (file_type is null or file_type in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf')),
  file_size integer check (file_size is null or file_size between 1 and 10485760),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists handouts_campaign_idx on public.handouts (campaign_id, created_at desc);

create table if not exists public.handout_recipients (
  handout_id uuid not null references public.handouts (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  primary key (handout_id, user_id)
);

alter table public.handouts enable row level security;
alter table public.handout_recipients enable row level security;
revoke all on public.handouts from anon, authenticated;
revoke all on public.handout_recipients from anon, authenticated;

drop trigger if exists handouts_touch on public.handouts;
create trigger handouts_touch before update on public.handouts
  for each row execute function public.touch_updated_at();

create or replace function public.can_read_handout(p_handout uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.handouts h
    where h.id = p_handout
      and (
        public.is_campaign_manager(h.campaign_id)
        or (h.visibility = 'all' and public.is_campaign_member(h.campaign_id))
        or (h.visibility = 'selected' and public.is_campaign_member(h.campaign_id) and exists (
              select 1 from public.handout_recipients r where r.handout_id = h.id and r.user_id = auth.uid()))
      )
  );
$$;
revoke execute on function public.can_read_handout(uuid) from public, anon;
grant execute on function public.can_read_handout(uuid) to authenticated;

grant select, delete on public.handouts to authenticated;
grant insert (id, campaign_id, title, body, visibility, file_path, file_name, file_type, file_size) on public.handouts to authenticated;
grant update (title, body, visibility) on public.handouts to authenticated;

drop policy if exists "Read handouts" on public.handouts;
create policy "Read handouts" on public.handouts for select to authenticated
  using (public.can_read_handout(id));
drop policy if exists "Managers add handouts" on public.handouts;
create policy "Managers add handouts" on public.handouts for insert to authenticated
  with check (public.is_campaign_manager(campaign_id) and author_id = (select auth.uid()));
drop policy if exists "Managers edit handouts" on public.handouts;
create policy "Managers edit handouts" on public.handouts for update to authenticated
  using (public.is_campaign_manager(campaign_id)) with check (public.is_campaign_manager(campaign_id));
drop policy if exists "Managers delete handouts" on public.handouts;
create policy "Managers delete handouts" on public.handouts for delete to authenticated
  using (public.is_campaign_manager(campaign_id));

-- Recipients: managers manage; each person can see their own entries.
grant select, insert, delete on public.handout_recipients to authenticated;
drop policy if exists "See handout recipients" on public.handout_recipients;
create policy "See handout recipients" on public.handout_recipients for select to authenticated
  using (
    user_id = (select auth.uid())
    or exists (select 1 from public.handouts h where h.id = handout_id and public.is_campaign_manager(h.campaign_id))
  );
drop policy if exists "Managers choose recipients" on public.handout_recipients;
create policy "Managers choose recipients" on public.handout_recipients for insert to authenticated
  with check (exists (
    select 1 from public.handouts h
    join public.campaign_members m on m.campaign_id = h.campaign_id and m.user_id = handout_recipients.user_id
    where h.id = handout_id and public.is_campaign_manager(h.campaign_id)
  ));
drop policy if exists "Managers remove recipients" on public.handout_recipients;
create policy "Managers remove recipients" on public.handout_recipients for delete to authenticated
  using (exists (select 1 from public.handouts h where h.id = handout_id and public.is_campaign_manager(h.campaign_id)));

create or replace function public.audit_handouts()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform public.log_activity(new.campaign_id, 'handout_created', jsonb_build_object('title', new.title));
  else
    perform public.log_activity(old.campaign_id, 'handout_deleted', jsonb_build_object('title', old.title));
  end if;
  return null;
end;
$$;
drop trigger if exists audit_handouts on public.handouts;
create trigger audit_handouts after insert or delete on public.handouts
  for each row execute function public.audit_handouts();

-- ---------------------------------------------------------------
-- File storage: a private bucket. Files live at
-- <campaign id>/<handout id>/<file name>.
-- ---------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('handouts', 'handouts', false, 10485760,
        array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

create or replace function public.handout_folder_campaign(p_name text)
returns uuid
language plpgsql immutable
set search_path = ''
as $$
declare
  v_first text := split_part(p_name, '/', 1);
begin
  return v_first::uuid;
exception when others then
  return null;
end;
$$;

create or replace function public.can_read_handout_file(p_name text)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.handouts h
    where h.file_path = p_name and public.can_read_handout(h.id)
  );
$$;
revoke execute on function public.can_read_handout_file(text) from public, anon;
grant execute on function public.can_read_handout_file(text) to authenticated;
grant execute on function public.handout_folder_campaign(text) to authenticated;

drop policy if exists "Handout files: read" on storage.objects;
create policy "Handout files: read" on storage.objects for select to authenticated
  using (
    bucket_id = 'handouts'
    and (public.can_read_handout_file(name)
         or coalesce(public.is_campaign_manager(public.handout_folder_campaign(name)), false))
  );

drop policy if exists "Handout files: upload" on storage.objects;
create policy "Handout files: upload" on storage.objects for insert to authenticated
  with check (
    bucket_id = 'handouts'
    and coalesce(public.is_campaign_manager(public.handout_folder_campaign(name)), false)
  );

drop policy if exists "Handout files: delete" on storage.objects;
create policy "Handout files: delete" on storage.objects for delete to authenticated
  using (
    bucket_id = 'handouts'
    and coalesce(public.is_campaign_manager(public.handout_folder_campaign(name)), false)
  );

-- =====================================================================
-- 0011_rolls.sql
-- =====================================================================

-- 0011: fair dice rolls and DM roll requests.
-- Run once in Supabase -> SQL Editor (New query). Safe to re-run.

create table if not exists public.roll_requests (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  label text not null check (char_length(label) between 1 and 60),
  dice_count integer not null check (dice_count between 1 and 20),
  dice_sides integer not null check (dice_sides between 2 and 100),
  bonus integer not null default 0 check (bonus between -100 and 100),
  modifier_field text check (modifier_field is null or modifier_field ~ '^[a-z][a-z0-9_]{0,39}$'),
  keep text not null default 'normal' check (keep in ('normal', 'highest', 'lowest')),
  share_results boolean not null default false,
  status text not null default 'open' check (status in ('open', 'closed')),
  created_at timestamptz not null default now()
);
create index if not exists roll_requests_campaign_idx on public.roll_requests (campaign_id, created_at desc);

create table if not exists public.roll_request_targets (
  request_id uuid not null references public.roll_requests (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  primary key (request_id, user_id)
);

create table if not exists public.roll_results (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.roll_requests (id) on delete cascade,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  character_id uuid references public.characters (id) on delete set null,
  method text not null check (method in ('app', 'manual')),
  dice integer[],
  dice_other integer[],
  modifier integer not null default 0,
  modifier_label text not null default '' check (char_length(modifier_label) <= 80),
  total integer not null,
  created_at timestamptz not null default now(),
  unique (request_id, user_id)
);
create index if not exists roll_results_campaign_idx on public.roll_results (campaign_id, created_at desc);

alter table public.roll_requests enable row level security;
alter table public.roll_request_targets enable row level security;
alter table public.roll_results enable row level security;
revoke all on public.roll_requests from anon, authenticated;
revoke all on public.roll_request_targets from anon, authenticated;
revoke all on public.roll_results from anon, authenticated;

create or replace function public.is_roll_target(p_request uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.roll_request_targets where request_id = p_request and user_id = auth.uid());
$$;
revoke execute on function public.is_roll_target(uuid) from public, anon;
grant execute on function public.is_roll_target(uuid) to authenticated;

-- Requests: DMs see all of their campaign's; players see the ones aimed at them.
grant select on public.roll_requests to authenticated;
drop policy if exists "See roll requests" on public.roll_requests;
create policy "See roll requests" on public.roll_requests for select to authenticated
  using (public.is_campaign_manager(campaign_id) or (public.is_roll_target(id) and public.is_campaign_member(campaign_id)));

grant select on public.roll_request_targets to authenticated;
drop policy if exists "See roll targets" on public.roll_request_targets;
create policy "See roll targets" on public.roll_request_targets for select to authenticated
  using (
    user_id = (select auth.uid())
    or exists (select 1 from public.roll_requests r where r.id = request_id and public.is_campaign_manager(r.campaign_id))
  );

-- Results: DMs and the person who rolled. (Shared results go to chat.)
grant select on public.roll_results to authenticated;
drop policy if exists "See roll results" on public.roll_results;
create policy "See roll results" on public.roll_results for select to authenticated
  using (user_id = (select auth.uid()) or public.is_campaign_manager(campaign_id));

-- A fair die: secure random bytes, so nobody can predict or replay a roll.
create or replace function public.roll_die(p_sides integer)
returns integer
language sql volatile
set search_path = ''
as $$
  select (('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint % p_sides)::integer + 1;
$$;
revoke execute on function public.roll_die(integer) from public, anon, authenticated;

create or replace function public.create_roll_request(
  p_campaign uuid, p_label text, p_count integer, p_sides integer, p_bonus integer,
  p_modifier_field text, p_keep text, p_share boolean, p_targets uuid[]
)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.is_campaign_manager(p_campaign) then raise exception 'not_allowed'; end if;
  if p_targets is null or cardinality(p_targets) = 0 then raise exception 'no_targets'; end if;
  if exists (
    select 1 from unnest(p_targets) t(id)
    where not exists (select 1 from public.campaign_members m where m.campaign_id = p_campaign and m.user_id = t.id)
  ) then raise exception 'not_a_member'; end if;

  insert into public.roll_requests (campaign_id, created_by, label, dice_count, dice_sides, bonus, modifier_field, keep, share_results)
  values (p_campaign, auth.uid(), trim(p_label), p_count, p_sides, coalesce(p_bonus, 0),
          nullif(trim(coalesce(p_modifier_field, '')), ''), coalesce(p_keep, 'normal'), coalesce(p_share, false))
  returning id into v_id;
  insert into public.roll_request_targets (request_id, user_id)
  select v_id, t.id from (select distinct unnest(p_targets) as id) t;
  return v_id;
end;
$$;

-- Shared results become a chat message from the roller.
create or replace function public.post_roll_to_chat(p_request public.roll_requests, p_text text)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if p_request.share_results then
    insert into public.messages (campaign_id, author_id, body)
    values (p_request.campaign_id, auth.uid(), left(p_text, 2000));
  end if;
end;
$$;
revoke execute on function public.post_roll_to_chat(public.roll_requests, text) from public, anon, authenticated;

create or replace function public.roll_for_request(
  p_request uuid, p_modifier integer default 0, p_modifier_label text default '', p_character uuid default null
)
returns public.roll_results
language plpgsql security definer set search_path = ''
as $$
declare
  r public.roll_requests;
  v_dice integer[] := '{}';
  v_other integer[];
  v_kept integer;
  v_other_sum integer;
  v_result public.roll_results;
  i integer;
begin
  select * into r from public.roll_requests where id = p_request;
  if r.id is null or not public.is_roll_target(p_request) or not public.is_campaign_member(r.campaign_id) then
    raise exception 'not_allowed';
  end if;
  if r.status <> 'open' then raise exception 'request_closed'; end if;
  if exists (select 1 from public.roll_results where request_id = p_request and user_id = auth.uid()) then
    raise exception 'already_rolled';
  end if;
  if p_modifier is null or p_modifier not between -100 and 100 then raise exception 'invalid_input'; end if;
  if p_character is not null and not exists (
    select 1 from public.characters ch
    join public.campaign_characters cc on cc.character_id = ch.id
    where ch.id = p_character and ch.owner_id = auth.uid() and cc.campaign_id = r.campaign_id
  ) then raise exception 'not_allowed'; end if;

  for i in 1..r.dice_count loop
    v_dice := v_dice || public.roll_die(r.dice_sides);
  end loop;
  v_kept := (select sum(x) from unnest(v_dice) x);

  if r.keep <> 'normal' then
    v_other := '{}';
    for i in 1..r.dice_count loop
      v_other := v_other || public.roll_die(r.dice_sides);
    end loop;
    v_other_sum := (select sum(x) from unnest(v_other) x);
    if (r.keep = 'highest' and v_other_sum > v_kept) or (r.keep = 'lowest' and v_other_sum < v_kept) then
      -- Keep the second set; store the first as the "other" roll.
      select v_other, v_dice into v_dice, v_other;
      v_kept := v_other_sum;
    end if;
  end if;

  insert into public.roll_results
    (request_id, campaign_id, user_id, character_id, method, dice, dice_other, modifier, modifier_label, total)
  values
    (p_request, r.campaign_id, auth.uid(), p_character, 'app', v_dice, v_other, p_modifier,
     left(coalesce(p_modifier_label, ''), 80), v_kept + r.bonus + p_modifier)
  returning * into v_result;

  perform public.post_roll_to_chat(
    r,
    format('🎲 %s: %s (rolled %s%s%s)', r.label, v_result.total, array_to_string(v_dice, ' + '),
      case when r.bonus <> 0 then format(' %s %s', case when r.bonus > 0 then '+' else '-' end, abs(r.bonus)) else '' end,
      case when p_modifier <> 0 then format(' %s %s %s', case when p_modifier > 0 then '+' else '-' end, abs(p_modifier),
        nullif(left(coalesce(p_modifier_label, ''), 40), '')) else '' end)
  );
  return v_result;
end;
$$;

create or replace function public.submit_manual_roll(p_request uuid, p_total integer)
returns public.roll_results
language plpgsql security definer set search_path = ''
as $$
declare
  r public.roll_requests;
  v_result public.roll_results;
begin
  select * into r from public.roll_requests where id = p_request;
  if r.id is null or not public.is_roll_target(p_request) or not public.is_campaign_member(r.campaign_id) then
    raise exception 'not_allowed';
  end if;
  if r.status <> 'open' then raise exception 'request_closed'; end if;
  if exists (select 1 from public.roll_results where request_id = p_request and user_id = auth.uid()) then
    raise exception 'already_rolled';
  end if;
  if p_total is null or p_total not between -1000 and 10000 then raise exception 'invalid_input'; end if;

  insert into public.roll_results (request_id, campaign_id, user_id, method, total)
  values (p_request, r.campaign_id, auth.uid(), 'manual', p_total)
  returning * into v_result;
  perform public.post_roll_to_chat(r, format('🎲 %s: %s (rolled at the table)', r.label, p_total));
  return v_result;
end;
$$;

create or replace function public.close_roll_request(p_request uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_campaign uuid;
begin
  select campaign_id into v_campaign from public.roll_requests where id = p_request;
  if v_campaign is null or not public.is_campaign_manager(v_campaign) then raise exception 'not_allowed'; end if;
  update public.roll_requests set status = 'closed' where id = p_request;
end;
$$;

revoke execute on function public.create_roll_request(uuid, text, integer, integer, integer, text, text, boolean, uuid[]) from public, anon;
revoke execute on function public.roll_for_request(uuid, integer, text, uuid) from public, anon;
revoke execute on function public.submit_manual_roll(uuid, integer) from public, anon;
revoke execute on function public.close_roll_request(uuid) from public, anon;
grant execute on function public.create_roll_request(uuid, text, integer, integer, integer, text, text, boolean, uuid[]) to authenticated;
grant execute on function public.roll_for_request(uuid, integer, text, uuid) to authenticated;
grant execute on function public.submit_manual_roll(uuid, integer) to authenticated;
grant execute on function public.close_roll_request(uuid) to authenticated;

-- Live updates for requests and results (the read rules above still apply).
do $$
declare
  t text;
begin
  foreach t in array array['roll_requests', 'roll_results'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;
